import Foundation
import AppKit
import CoreGraphics
import PDFKit
import Darwin

// Compiled only with temporary instrumented copies of the production audit.
// Every input is generated by QPDFStructuralAudit, never a user document.
enum CIDiagnostics { static func record(_ message: String, level: String = "notice", title: String = "") {} }
final class NativeCancellation: @unchecked Sendable {
    private let lock = NSLock()
    private var cancelled = false
    func cancel() { lock.lock(); cancelled = true; lock.unlock() }
    func check() throws { lock.lock(); let value = cancelled; lock.unlock(); if value { throw CancellationError() } }
}
enum NativeOutput {
    static func write(_ bytes: Data, to url: URL) throws {
        let descriptor = Darwin.open(url.path, O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW | O_CLOEXEC, mode_t(0o600))
        guard descriptor >= 0 else { throw NSError(domain: "PDF.ExactDiagnosis", code: 1) }
        let file = FileHandle(fileDescriptor: descriptor, closeOnDealloc: true)
        defer { try? file.close() }
        try file.write(contentsOf: bytes); try file.synchronize()
    }
}

enum ExactAuditCapture {
    static var currentDirectory = URL(fileURLWithPath: "/tmp")
    static var lastEditablePlain: Data?
    private static var snapshotIndex = 0

    static func snapshot(_ document: PDFDocument, label: String) throws {
        snapshotIndex += 1
        let url = currentDirectory.appendingPathComponent(String(format: "%03d-", snapshotIndex) + label + ".json")
        // The independent legacy-permission controls have different synthetic
        // page text. Do not make optional diagnostic getters a new audit gate.
        let text = document.isLocked ? "" : (document.string ?? "")
        guard text.contains("PDF native verification") || text.contains("PDF structural verification") else {
            let record: [String: Any] = ["syntheticFixture": true, "detailedAnnotationCapture": false,
                "pageCount": document.pageCount, "isEncrypted": document.isEncrypted, "isLocked": document.isLocked]
            try NativeOutput.write(JSONSerialization.data(withJSONObject: record, options: [.sortedKeys]), to: url)
            return
        }
        let record = try MainActor.assumeIsolated { try PDFKitDiagnosis.annotationSnapshot(document, progressPrefix: url) }
        try NativeOutput.write(JSONSerialization.data(withJSONObject: PDFKitDiagnosis.diagnosticJSON(record), options: [.prettyPrinted, .sortedKeys]), to: url)
        let keys: Set<String> = ["index", "type", "contents", "bounds", "flags", "isOpen", "rawOpen", "parent", "rawParent",
                                 "popup", "rawPopup", "field", "fieldType", "value", "default", "choices", "choiceValues", "list",
                                 "color", "fontColor", "fontName", "fontSize", "rawDefaultAppearance"]
        let selected = (record["annotations"] as? [[String: Any]] ?? []).filter {
            ["text", "popup", "widget", "freetext"].contains(($0["type"] as? String ?? "").replacingOccurrences(of: "/", with: "").lowercased())
        }.map { $0.filter { keys.contains($0.key) } }
        let summary: [String: Any] = ["syntheticSnapshot": url.lastPathComponent, "annotations": selected]
        FileHandle.standardOutput.write(try JSONSerialization.data(withJSONObject: PDFKitDiagnosis.diagnosticJSON(summary), options: [.sortedKeys]) + Data([10]))
    }

    final class Logs {
        let out: FileHandle?
        let error: FileHandle
        let status: URL
        init(out: FileHandle?, error: FileHandle, status: URL) { self.out = out; self.error = error; self.status = status }
        func check() throws {
            for file in [out, error].compactMap({ $0 }) {
                var info = stat()
                guard fstat(file.fileDescriptor, &info) == 0, info.st_size <= 1_048_576 else {
                    throw NSError(domain: "PDF.ExactDiagnosis", code: 2, userInfo: [NSLocalizedDescriptionKey: "Bounded diagnostic log exceeded 1 MiB"])
                }
            }
        }
        func record(_ process: Process) {
            try? check()
            let data: [String: Any] = ["exitCode": process.terminationStatus, "exitedNormally": process.terminationReason == .exit]
            if let bytes = try? JSONSerialization.data(withJSONObject: data, options: [.sortedKeys]) { try? NativeOutput.write(bytes, to: status) }
        }
        func close() { try? out?.close(); try? error.close() }
    }
    static func attach(_ process: Process, directory: URL, stdout: FileHandle?) throws -> Logs {
        let identifier = UUID().uuidString
        func stream(_ suffix: String) throws -> FileHandle {
            let url = directory.appendingPathComponent("trace-" + identifier + suffix)
            try NativeOutput.write(Data(), to: url)
            return try FileHandle(forWritingTo: url)
        }
        let out: FileHandle?
        if stdout == nil { out = try stream(".stdout") } else { out = nil }
        let error = try stream(".stderr")
        process.standardOutput = stdout ?? out; process.standardError = error
        return Logs(out: out, error: error, status: directory.appendingPathComponent("trace-" + identifier + ".status.json"))
    }
}

@main
struct ExactSerializationDiagnosis {
    @MainActor static func main() {
        _ = NSApplication.shared
        guard CommandLine.arguments.count == 2 else { exit(2) }
        let root = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
        do {
            guard Darwin.mkdir(root.path, mode_t(0o700)) == 0 else { throw NSError(domain: "PDF.ExactDiagnosis", code: 3) }
            var phases: [[String: Any]] = []
            func phase(_ name: String, action: () throws -> Void) throws {
                let folder = root.appendingPathComponent(name, isDirectory: true)
                try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: false, attributes: [.posixPermissions: 0o700])
                ExactAuditCapture.currentDirectory = folder
                var record: [String: Any] = ["name": name, "productValidation": false]
                do { try action(); record["status"] = "passed" }
                catch {
                    let issue = error as NSError
                    record["status"] = "failed"; record["domain"] = issue.domain; record["code"] = issue.code
                    record["message"] = issue.localizedDescription
                    record["diagnosticLine"] = issue.userInfo["diagnosticLine"] as Any? ?? NSNull()
                }
                phases.append(record)
                let bytes = try JSONSerialization.data(withJSONObject: record, options: [.sortedKeys])
                try NativeOutput.write(bytes, to: folder.appendingPathComponent("phase.json"))
                FileHandle.standardOutput.write(bytes + Data([10]))
            }
            try phase("editable-exact") { try QPDFStructuralAudit.verifyEditableRoundTrips() }
            try phase("explicit-annotations-independent") {
                guard let bytes = ExactAuditCapture.lastEditablePlain else {
                    throw NSError(domain: "PDF.ExactDiagnosis", code: 4, userInfo: [NSLocalizedDescriptionKey: "No validated editable plain result was available in this run"])
                }
                try QPDFStructuralAudit.verifyExplicitAnnotationGuards(base: bytes)
            }
            try NativeOutput.write(JSONSerialization.data(withJSONObject: ["phases": phases, "productValidation": false], options: [.prettyPrinted, .sortedKeys]),
                                   to: root.appendingPathComponent("exact-summary.json"))
        } catch {
            FileHandle.standardError.write(Data("Exact synthetic diagnosis could not complete its capture.\n".utf8)); exit(1)
        }
    }

}
